// Authenticated internal endpoint: only the CRM may call it, using a shared
// secret held server-side. Twilio credentials stay in n8n env/credentials.
const crypto = require('crypto');
const item = $input.all()[0];
const body = item.json.body || {};
const headers = item.json.headers || {};

const expected = $env.CRM_SEND_SECRET || '';
const provided = headers['x-send-secret'] || '';
if (!expected || !provided || provided.length !== expected.length ||
    !crypto.timingSafeEqual(Buffer.from(provided), Buffer.from(expected))) {
  return [{ json: { reject: true, status: 401, message: 'unauthorized' } }];
}

const to = String(body.to || '').trim();
const text = String(body.body || '').trim();
if (!to.startsWith('+') || !text) {
  return [{ json: { reject: true, status: 422, message: 'to (E.164) and body are required' } }];
}
const accountSid = $env.TWILIO_ACCOUNT_SID || '';
const authToken = $env.TWILIO_AUTH_TOKEN || '';
if (!accountSid || !authToken) {
  return [{ json: { reject: true, status: 503, message: 'messaging not configured' } }];
}
// Credentials come from the environment and are never stored in this export.
const authHeader = 'Basic ' + Buffer.from(accountSid + ':' + authToken).toString('base64');

return [{
  json: {
    reject: false,
    message_id: String(body.message_id || ''),
    to,
    body: text,
    from: $env.TWILIO_FROM_NUMBER || '',
    account_sid: accountSid,
    auth_header: authHeader,
    status_callback: ($env.TWILIO_WEBHOOK_BASE_URL || '') + '/webhook/twilio-status',
  },
}];

// Translate the Twilio response into the CRM's send outcome.
//
// Ambiguity is never upgraded to a definite result: Twilio may have accepted
// the message before the response was lost, so a transport failure, timeout,
// 5xx, malformed body or a nominal 2xx without a SID all report 'unknown'.
// Only a parseable 4xx rejection is a definite 'failed'. Nothing from the
// credentials or authorization headers is echoed.
const response = $input.all()[0].json;
const status = Number(response.statusCode || 0);
const body = response.body && typeof response.body === 'object' ? response.body : null;

function bounded(value, fallback) {
  return String(value === undefined || value === null || value === '' ? fallback : value)
    .slice(0, 300);
}

// No status at all: the request never produced an HTTP response.
if (!status) {
  return [{ json: { status: 'unknown', error_code: 'transport_error',
    error_message: 'No response from the provider; delivery is unconfirmed.' } }];
}
if (status >= 200 && status < 300) {
  if (body && body.sid) {
    return [{ json: { status: 'submitted', sid: String(body.sid).slice(0, 64),
      provider_status: body.status ? String(body.status).slice(0, 32) : null } }];
  }
  // Accepted-looking response we cannot tie to a message id.
  return [{ json: { status: 'unknown', error_code: 'no_sid',
    error_message: 'The provider accepted the request without returning a message id.' } }];
}
if (status >= 400 && status < 500 && body && (body.code || body.message)) {
  return [{ json: { status: 'failed',
    error_code: String(body.code || status).slice(0, 32),
    error_message: bounded(body.message, 'Provider rejected the message.') } }];
}
// 5xx, or a 4xx we cannot parse: the provider's true state is unknown.
return [{ json: { status: 'unknown', error_code: String(status).slice(0, 32),
  error_message: 'The provider did not confirm the outcome.' } }];
